        continue
    for a in data:
        if a.get('labels',{}).get('namespace')=='otel-demo':
            alerts.append((a['labels'].get('alertname'), a['labels'].get('severity'), a.get('state')))
# dedup
unique=set(alerts)
for name,sev,state in sorted(unique):
    print(name,sev,state)
